impl<'a> Built<'a> {
    /// Pass 1 walks the tree collecting scopes, bindings, with sites,
    /// import sites, and every expression-position ident token. Pass 2
    /// resolves each collected ident against the finished scope table
    /// and fills `Binding.references`. Two passes are required because
    /// `rec` makes names visible *before* their defining value: a
    /// binding must exist before the values are resolved, so resolution
    /// cannot happen during the walk.
    fn build(source: &'a str, root: &'a SyntaxNode) -> Self {
        let mut builder = Builder {
            source,
            scopes: Vec::new(),
            bindings: Vec::new(),
            with_sites: Vec::new(),
            import_sites: Vec::new(),
            idents: Vec::new(),
            stack: Vec::new(),
        };
        builder.new_scope(ScopeKind::Root, root.range());
        if let Some(expr) = Root::cast(root).and_then(|r| r.expr()) {
            builder.walk_expr(expr);
        }
        let mut built = Self {
            source,
            scopes: builder.scopes,
            bindings: builder.bindings,
            references: Vec::new(),
            with_sites: builder.with_sites,
            import_sites: builder.import_sites,
        };
        for token in builder.idents {
            built.record_reference(token);
        }
        built
    }

    fn record_reference(&mut self, token: &'a SyntaxToken) {
        let offset = token.range().start();
        let name = token.text(self.source);
        let mut resolved = self.resolve_lexical_index(name, offset);
        let mut via_with = None;
        if resolved.is_none() {
            via_with = self.with_fallback(offset);
        }
        if let Some(bi) = resolved {
            self.bindings[bi].references.push(token.range());
        }
        self.references.push(Reference { name: token, resolved, via_with });
    }

    fn resolve_lexical_index(&self, name: &str, offset: u32) -> Option<usize> {
        let mut scope_id = self.innermost_scope(offset)?;
        loop {
            let scope = &self.scopes[scope_id.0 as usize];
            if scope.kind != ScopeKind::Attrset {
                for pos in scope.bindings.start..scope.bindings.end {
                    let binding = &self.bindings[pos];
                    if binding.name.text(self.source) == name
                        && self.is_visible(scope_id, pos - scope.bindings.start, offset)
                    {
                        return Some(pos);
                    }
                }
            }
            scope_id = scope.parent?;
        }
    }
    ...
}
