innermost_scope:
```rust
/// The innermost scope whose range contains `offset`. Scopes nest
/// strictly (each new scope's range is inside its parent's), and are
/// created depth-first in source order, so the last scope containing
/// the offset is the innermost.
fn innermost_scope(&self, offset: u32) -> Option<ScopeId> {
    self.scopes
        .iter()
        .enumerate()
        .rev()
        .find(|(_, s)| s.range.contains(offset))
        .map(|(i, _)| ScopeId(i as u32))
}
