/// The innermost `with` whose body contains `offset`, if any. Sites are
/// recorded in source order, so a reverse scan finds the innermost one
/// first (a nested with's body is a subrange of its enclosing with's).
fn with_fallback(&self, offset: u32) -> Option<usize> {
    self.with_sites
        .iter()
        .enumerate()
        .rev()
        .find(|(_, w)| w.body_range.contains(offset))
        .map(|(i, _)| i)
}
