Expr::Lambda(lambda) => {
    let scope = self.new_scope(ScopeKind::Lambda, lambda.range());
    match lambda.param() {
        LambdaParam::Ident(token) => {
            // `x: body` — x is visible in the body, never in itself.
            self.register(token, BindingKind::LambdaParam, scope, token.range().end());
        }
        LambdaParam::Formals(formals, at_name) => {
            for param in formals.params() {
                if let Some(default) = param.default {
                    self.walk_expr(default);
                }
                // Sequential like let: param i visible in defaults of
                // j > i (its own default is walked above and excluded).
                let visible_from = param
                    .default
                    .map(|d| d.range().end())
                    .unwrap_or(param.name.range().end());
                self.register(param.name, BindingKind::LambdaParam, scope, visible_from);
            }
            if let Some(at) = at_name {
                // The at-name is visible only in the body, whichever
                // side of the formals it sits on.
                let visible_from = formals.range().end().max(at.range().end());
                self.register(at, BindingKind::AtName, scope, visible_from);
            }
        }
    }
    if let Some(body) = lambda.body() {
        self.walk_expr(body);
    }
    self.pop_scope();
}
