const tests = `//! Integration tests for the M4 semantic model.
//!
//! These pin the Nix scoping rules the model implements — let
//! sequentiality (including the \`let x = x;\` gotcha), rec mutual
//! visibility, formals defaults, the at-name, inherit, the with
//! fallback, import detection, and the laziness/malformed-input
//! guarantees. Reference indices below are indexes into
//! \`model.bindings()\` / \`model.references()\`, which are both in
//! source order.

use strictix_core::semantic::{BindingKind, SemanticModel};
use strictix_syntax::parse;

/// Parse \`src\`, build a model over it, and hand both the model and the
/// source text to \`f\`. The tree stays alive for the whole closure, so
/// the model's borrowed references are valid inside it.
fn with_model(src: &str, f: impl for<'a> FnOnce(&'a str, SemanticModel<'a>)) {
    let root = parse(src);
    let model = SemanticModel::new(src, &root);
    f(src, model);
}

#[test]
fn let_shadowing() {
    with_model("let a = 1; in let a = 2; in a", |_src, m| {
        let bindings = m.bindings();
        assert_eq!(bindings.len(), 2, "outer and inner 'a' are distinct bindings");
        // Two separate Binding entries with different defining tokens.
        assert_ne!(bindings[0].name.range(), bindings[1].name.range());
        assert_eq!(bindings[0].kind, BindingKind::LetBinding);
        assert_eq!(bindings[1].kind, BindingKind::LetBinding);
        // The body reference resolves to the inner binding.
        let refs = m.references();
        assert_eq!(refs.len(), 1);
        assert_eq!(refs[0].resolved, Some(1));
        assert_eq!(refs[0].via_with, None);
    });
}

#[test]
fn let_sequential_visibility() {
    // y's value sees the outer x.
    with_model("let x = 1; in let y = x; in y", |_src, m| {
        let refs = m.references();
        assert_eq!(refs.len(), 2);
        assert_eq!(refs[0].resolved, Some(0), "x in y's value resolves to outer x");
        assert_eq!(refs[1].resolved, Some(1), "body y resolves to inner y");
        // The outer binding's references list contains the use in y's value.
        assert_eq!(m.bindings()[0].references.len(), 1);
    });

    // The gotcha: a binding is not visible in its own value.
    with_model("let x = x; in x", |_src, m| {
        let refs = m.references();
        assert_eq!(refs.len(), 2);
        assert_eq!(refs[0].resolved, None, "x in its own value resolves to nothing");
        assert_eq!(refs[0].via_with, None);
        assert_eq!(refs[1].resolved, Some(0), "body x resolves to the binding");
        // Only the body use lands in the binding's references.
        assert_eq!(m.bindings()[0].references.len(), 1);
    });
}

#[test]
fn rec_self_reference() {
    with_model("rec { a = 1; b = a; }", |_src, m| {
        let bindings = m.bindings();
        assert_eq!(bindings.len(), 2);
        assert_eq!(bindings[0].kind, BindingKind::RecAttr);
        assert_eq!(bindings[1].kind, BindingKind::RecAttr);
        let refs = m.references();
        assert_eq!(refs.len(), 1);
        assert_eq!(refs[0].resolved, Some(0), "b's value a resolves to the rec attr a");
        assert_eq!(m.bindings()[0].references.len(), 1);
    });
}

#[test]
fn formals_defaults() {
    with_model("{ a, b ? a }: b", |_src, m| {
        assert_eq!(m.bindings().len(), 2);
        let refs = m.references();
        assert_eq!(refs.len(), 2);
        assert_eq!(refs[0].resolved, Some(0), "default a resolves to param a");
        assert_eq!(refs[1].resolved, Some(1), "body b resolves to param b");
    });
}

#[test]
fn at_name_binding() {
    with_model("args@{ a }: args", |_src, m| {
        let bindings = m.bindings();
        assert_eq!(bindings.len(), 2);
        assert_eq!(bindings[0].kind, BindingKind::LambdaParam);
        assert_eq!(bindings[1].kind, BindingKind::AtName);
        let refs = m.references();
        assert_eq!(refs.len(), 1, "the formal 'a' is not a reference");
        assert_eq!(refs[0].resolved, Some(1), "body args resolves to the at-name");
    });
}

#[test]
fn inherit_in_let() {
    with_model("let x = 1; inherit (x) y; in y", |_src, m| {
        let bindings = m.bindings();
        assert_eq!(bindings.len(), 2);
        assert_eq!(bindings[1].kind, BindingKind::LetBinding, "inherit names in a let are LetBinding");
        let refs = m.references();
        assert_eq!(refs.len(), 2);
        assert_eq!(refs[0].resolved, Some(0), "the (x) source resolves to the let's x");
        assert_eq!(refs[1].resolved, Some(1), "body y resolves to the inherited y");
    });
}

#[test]
fn with_fallback() {
    with_model("with { a = 1; }; a", |_src, m| {
        assert_eq!(m.with_sites().len(), 1);
        let refs = m.references();
        assert_eq!(refs.len(), 1);
        assert_eq!(refs[0].resolved, None, "no lexical binding for a");
        assert_eq!(refs[0].via_with, Some(0), "innermost covering with recorded");
    });
}

#[test]
fn lexical_beats_with() {
    with_model("let a = 1; in with { a = 2; }; a", |_src, m| {
        let refs = m.references();
        assert_eq!(refs.len(), 1);
        assert_eq!(refs[0].resolved, Some(0), "body a resolves to the let binding");
        assert_eq!(refs[0].via_with, None, "no fallback when lexical wins");
    });
}

#[test]
fn unbound_reference() {
    with_model("frobnicate", |_src, m| {
        assert_eq!(m.references().len(), 1);
        assert_eq!(m.references()[0].resolved, None);
        assert_eq!(m.references()[0].via_with, None);
        assert!(m.bindings().is_empty());
    });
}

#[test]
fn import_sites() {
    with_model("import ./foo.nix", |src, m| {
        let sites = m.import_sites();
        assert_eq!(sites.len(), 1);
        assert_eq!(
            &src[sites[0].path_range.start() as usize..sites[0].path_range.end() as usize],
            "./foo.nix",
            "path_range covers the path token"
        );
        assert!(sites[0].call_range.contains(sites[0].path_range.start()));
    });
    with_model("builtins.import ./foo.nix", |src, m| {
        assert_eq!(m.import_sites().len(), 1);
        let site = &m.import_sites()[0];
        assert_eq!(
            &src[site.path_range.start() as usize..site.path_range.end() as usize],
            "./foo.nix"
        );
    });
    // A non-import application records nothing.
    with_model("frobnicate ./foo.nix", |_src, m| {
        assert!(m.import_sites().is_empty());
    });
}

#[test]
fn lazy_and_malformed_do_not_panic() {
    // new() itself does no walking: constructing over broken sources
    // must not panic, and neither may the first (and only) build.
    for broken in ["let x =", "}", "let a = in a", "with;", "rec { a = }"] {
        let root = parse(broken);
        let m = SemanticModel::new(broken, &root);
        let _ = m.bindings();
        let _ = m.references();
        let _ = m.with_sites();
        let _ = m.import_sites();
    }
}

#[test]
fn attrpath_elements_are_not_references() {
    with_model("let a = { b = 1; }; in a.b", |src, m| {
        let refs = m.references();
        assert_eq!(refs.len(), 1, "b in a.b is not a reference");
        assert_eq!(refs[0].name.text(src), "a");
        assert_eq!(refs[0].resolved, Some(0));
    });
}

#[test]
fn reference_count_sanity() {
    with_model("a", |_src, m| {
        assert_eq!(m.references().len(), 1);
        assert_eq!(m.bindings().len(), 0);
    });
}

#[test]
fn resolve_api_by_range() {
    with_model("let a = 1; in a", |_src, m| {
        let tok = m.references()[0].name;
        let binding = m.resolve(tok).expect("reference resolves");
        assert_eq!(binding.name.range(), tok.range());
        // A non-reference token resolves to nothing.
        let let_token = parse("let a = 1; in a")
            .descendants()
            .flat_map(|n| n.child_tokens().cloned().collect::<Vec<_>>())
            .find(|t| t.text("let a = 1; in a") == "let")
            .expect("let keyword token");
        assert!(m.resolve(&let_token).is_none());
    });
}

#[test]
fn resolve_lexical_and_is_bound() {
    with_model("let a = 1; in a", |_src, m| {
        let offset = m.references()[0].name.range().start();
        assert!(m.resolve_lexical("a", offset).is_some());
        assert!(!m.resolve_lexical("b", offset).is_some());
        assert!(m.is_bound("a", offset));
        assert!(m.is_bound("b", offset) == false, "no with covers the offset");
    });
    // Inside a with body, is_bound is conservatively true for any name.
    with_model("with { a = 1; }; b", |_src, m| {
        let offset = m.references()[0].name.range().start();
        assert!(m.is_bound("b", offset), "the with body could provide b");
        assert_eq!(m.references()[0].resolved, None);
        assert_eq!(m.references()[0].via_with, Some(0));
    });
}

#[test]
fn interpolation_is_an_expression_position() {
    with_model("let a = 1; in \"\\${a}\"", |_src, m| {
        let refs = m.references();
        assert_eq!(refs.len(), 1, "interpolated a is a reference");
        assert_eq!(refs[0].resolved, Some(0));
    });
}

#[test]
fn nested_let_in_value_sees_outer_bindings() {
    // The inner let is inside the outer binding's value: it resolves
    // against earlier bindings of the outer let, not the outer let's
    // own binding (which is not visible in its own value).
    with_model("let a = (let b = a; in b); in a", |_src, m| {
        let refs = m.references();
        assert_eq!(refs.len(), 3);
        assert_eq!(refs[0].resolved, None, "a in its own value is invisible");
        assert_eq!(refs[1].resolved, Some(1), "b resolves to the inner binding");
        assert_eq!(refs[2].resolved, Some(0), "body a resolves to the outer binding");
    });
}
`;
