//! The semantic model: lexical scopes, bindings, references, with and
//! import sites, built lazily once per file.
//!
//! One walk of the tree produces the whole scope graph. Resolution follows
//! Nix semantics: lexical bindings win over with-scopes, and a `with` only
//! fills gaps. Let bindings are sequential — a binding is visible from the
//! end of its own value onward, never inside it — so `let x = x;` is a
//! reference to an outer (or unbound) `x`, which the self-referential-let
//! lint catches as the infinite recursion it is at evaluation time.
//!
//! The model is lazy: [SemanticModel::new] stores the source and tree and
//! walks nothing; the first accessor call builds everything once via
//! [std::cell::OnceCell]. Node rules never touch the model, so a file
//! containing only node-rule findings never pays for the walk.

use std::cell::OnceCell;

use strictix_syntax::{
    AstNode, AttrItem, AttrName, Expr, LambdaParam, StringPart, SyntaxKind as K, SyntaxNode,
    SyntaxToken, TextRange,
};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct ScopeId(pub u32);

/// What kind of construct introduced a binding.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BindingKind {
    /// `x: body` or a formal param in `{ a, b ? 1, ... }: body`.
    LambdaParam,
    /// The name bound by `args@{ ... }: body`.
    AtName,
    /// One entry of a `let` block (sequential visibility).
    LetBinding,
    /// One attribute of a `rec { ... }` set (mutually visible).
    RecAttr,
    /// A name pulled in by `inherit (src) a b;`.
    InheritName,
}

/// A name bound somewhere in the file.
pub struct Binding<'a> {
    /// The defining ident token.
    pub name: &'a SyntaxToken,
    pub kind: BindingKind,
    pub scope: ScopeId,
    /// Byte ranges of the uses that resolved to this binding.
    pub references: Vec<TextRange>,
}

/// One ident token used in expression position.
pub struct Reference<'a> {
    pub name: &'a SyntaxToken,
    /// Index into [SemanticModel::bindings] when the reference resolved to a
    /// lexical binding; `None` when no lexical binding was visible.
    pub resolved: Option<usize>,
    /// Index into [SemanticModel::with_sites] for references that could only
    /// be satisfied by a with-scope (the innermost candidate). Statically we
    /// cannot know whether the with actually provides the name.
    pub via_with: Option<usize>,
}

/// One `with e; body` site.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct WithSite {
    /// The scope expression (`e`).
    pub scope_range: TextRange,
    /// Everything after the semicolon.
    pub body_range: TextRange,
}

/// One `import e` (or `builtins.import e`) call site.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ImportSite {
    /// The whole call.
    pub call_range: TextRange,
    /// The argument expression.
    pub path_range: TextRange,
}

/// The lazily-built scope graph.
struct Built<'a> {
    source: &'a str,
    bindings: Vec<Binding<'a>>,
    references: Vec<Reference<'a>>,
    with_sites: Vec<WithSite>,
    import_sites: Vec<ImportSite>,
    scopes: Vec<Scope>,
}

/// A name visible in one scope, from one offset onward.
struct ScopeEntry {
    binding: usize,
    visible_from: u32,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ScopeKind {
    Root,
    Let,
    Lambda,
    Rec,
    With,
}

struct Scope {
    kind: ScopeKind,
    range: TextRange,
    /// For `With` scopes: the index into `with_sites`.
    with_site: Option<usize>,
    bindings: Vec<ScopeEntry>,
}

impl Scope {
    /// The visible candidate with the latest declaration order, if any.
    fn resolve(&self, name: &str, offset: u32, built: &Built) -> Option<usize> {
        if !self.range.contains(offset) {
            return None;
        }
        self.bindings
            .iter()
            .rev()
            .find(|e| {
                let b = &built.bindings[e.binding];
                offset >= e.visible_from && b.name.text(built.source) == name
            })
            .map(|e| e.binding)
    }
}

pub struct SemanticModel<'a> {
    source: &'a str,
    root: &'a SyntaxNode,
    built: OnceCell<Built<'a>>,
}

impl<'a> SemanticModel<'a> {
    /// Cheap: stores the source and root, walks nothing.
    #[must_use]
    pub fn new(source: &'a str, root: &'a SyntaxNode) -> Self {
        Self {
            source,
            root,
            built: OnceCell::new(),
        }
    }

    #[must_use]
    pub fn source(&self) -> &'a str {
        self.source
    }

    #[must_use]
    pub fn root(&self) -> &'a SyntaxNode {
        self.root
    }

    /// Trigger the one-time build; returns the graph borrowed from self.
    fn built(&self) -> &Built<'a> {
        self.built
            .get_or_init(|| Builder::new(self.source, self.root).build())
    }

    /// All bindings in source order. Triggers the build on first call.
    #[must_use]
    pub fn bindings(&self) -> &[Binding<'a>] {
        &self.built().bindings
    }

    /// All ident references in expression position, in source order.
    #[must_use]
    pub fn references(&self) -> &[Reference<'a>] {
        &self.built().references
    }

    /// All with-sites in source order.
    #[must_use]
    pub fn with_sites(&self) -> &[WithSite] {
        &self.built().with_sites
    }

    /// All import call sites in source order.
    #[must_use]
    pub fn import_sites(&self) -> &[ImportSite] {
        &self.built().import_sites
    }

    /// Resolve an ident token that belongs to this tree.
    ///
    /// Tokens are value types; identity is by byte range. A token that is
    /// not a reference (an attr name, a formal, ...) yields `None`.
    #[must_use]
    pub fn resolve(&self, token: &SyntaxToken) -> Option<&Binding<'a>> {
        let built = self.built();
        built.references
            .iter()
            .find(|r| r.name.range() == token.range())
            .and_then(|r| r.resolved)
            .map(|i| &built.bindings[i])
    }

    /// Nearest lexical binding visible at byte `offset` (no with fallback).
    ///
    /// Walks every scope whose range contains the offset, innermost first
    /// (the scope vector is built in push order, so iteration in reverse
    /// declaration order is innermost-out); the first scope with a visible
    /// candidate wins.
    #[must_use]
    pub fn resolve_lexical(&self, name: &str, offset: u32) -> Option<&Binding<'a>> {
        let built = self.built();
        for scope in built.scopes.iter().rev() {
            if scope.kind == ScopeKind::With {
                continue;
            }
            if let Some(i) = scope.resolve(name, offset, built) {
                return Some(&built.bindings[i]);
            }
        }
        None
    }

    /// Whether any binding (lexical or with fallback) could cover `name` at
    /// `offset`. The with fallback is sound here: we cannot prove the with
    /// lacks the name, so a with-scope on the path counts as bound.
    #[must_use]
    pub fn is_bound(&self, name: &str, offset: u32) -> bool {
        let built = self.built();
        for scope in built.scopes.iter().rev() {
            if scope.kind == ScopeKind::With {
                return true;
            }
            if scope.resolve(name, offset, built).is_some() {
                return true;
            }
        }
        false
    }
}

