// Builder: one walk of the tree builds the whole graph.

struct Builder<'a> {
    source: &'a str,
    root: &'a SyntaxNode,
    scopes: Vec<Scope>,
    stack: Vec<ScopeId>,
    bindings: Vec<Binding<'a>>,
    references: Vec<Reference<'a>>,
    with_sites: Vec<WithSite>,
    import_sites: Vec<ImportSite>,
}

impl<'a> Builder<'a> {
    fn new(source: &'a str, root: &'a SyntaxNode) -> Self {
        let mut b = Self {
            source,
            root,
            scopes: Vec::new(),
            stack: Vec::new(),
            bindings: Vec::new(),
            references: Vec::new(),
            with_sites: Vec::new(),
            import_sites: Vec::new(),
        };
        b.push_scope(ScopeKind::Root, root.range(), None);
        b
    }

    fn build(mut self) -> Built<'a> {
        if let Some(expr) = strictix_syntax::Root::cast(self.root).and_then(|r| r.expr()) {
            self.walk_expr(expr);
        }
        self.pop_scope();
        Built {
            source: self.source,
            bindings: self.bindings,
            references: self.references,
            with_sites: self.with_sites,
            import_sites: self.import_sites,
            scopes: self.scopes,
        }
    }

    fn push_scope(&mut self, kind: ScopeKind, range: TextRange, with_site: Option<usize>) -> ScopeId {
        let id = ScopeId(self.scopes.len() as u32);
        self.scopes.push(Scope {
            kind,
            range,
            with_site,
            bindings: Vec::new(),
        });
        self.stack.push(id);
        id
    }

    fn pop_scope(&mut self) {
        self.stack.pop();
    }

    fn top_scope(&self) -> ScopeId {
        *self.stack.last().expect("scope stack never empty")
    }

    /// Declare a binding in the current scope, visible from `visible_from`.
    fn declare(&mut self, name: &'a SyntaxToken, kind: BindingKind, visible_from: u32) -> usize {
        let scope = self.top_scope();
        let index = self.bindings.len();
        self.bindings.push(Binding {
            name,
            kind,
            scope,
            references: Vec::new(),
        });
        self.scopes[scope.0 as usize].bindings.push(ScopeEntry {
            binding: index,
            visible_from,
        });
        index
    }

    /// Lexical resolution: innermost scope with a visible candidate wins.
    fn resolve(&self, name: &str, offset: u32) -> Option<usize> {
        for &sid in self.stack.iter().rev() {
            let scope = &self.scopes[sid.0 as usize];
            if scope.kind == ScopeKind::With {
                continue;
            }
            if let Some(i) = scope.resolve(name, offset, self.source, &self.bindings) {
                return Some(i);
            }
        }
        None
    }

    /// Record an ident in expression position and resolve it.
    fn reference(&mut self, token: &'a SyntaxToken) {
        let name = token.text(self.source);
        let offset = token.range().start();
        let mut via_with = None;
        // Innermost with-scope whose body contains this offset is the
        // fallback candidate; only consulted when no lexical binding exists.
        for &sid in self.stack.iter().rev() {
            let scope = &self.scopes[sid.0 as usize];
            if scope.kind == ScopeKind::With {
                via_with = scope.with_site;
                continue;
            }
            if let Some(i) = scope.resolve(name, offset, self.source, &self.bindings) {
                self.bindings[i].references.push(token.range());
                self.references.push(Reference {
                    name: token,
                    resolved: Some(i),
                    via_with: None,
                });
                return;
            }
        }
        self.references.push(Reference {
            name: token,
            resolved: None,
            via_with,
        });
    }

    // --- the walk ----------------------------------------------------------

    fn walk_expr(&mut self, expr: Expr<'a>) {
        match expr {
            Expr::Ident(t) => self.reference(t),
            Expr::Let(e) => self.walk_let(e),
            Expr::With(w) => {
                if let Some(scope_expr) = w.scope() {
                    self.walk_expr(scope_expr);
                }
                let body = w.body();
                let body_range = body.map_or(w.range(), |b| b.range());
                let site_index = self.with_sites.len();
                self.with_sites.push(WithSite {
                    scope_range: w.scope().map_or(w.range(), |s| s.range()),
                    body_range,
                });
                self.push_scope(ScopeKind::With, body_range, Some(site_index));
                if let Some(body_expr) = body {
                    self.walk_expr(body_expr);
                }
                self.pop_scope();
            }
            Expr::Assert(a) => {
                if let Some(cond) = a.cond() {
                    self.walk_expr(cond);
                }
                if let Some(b) = a.body() {
                    self.walk_expr(b);
                }
            }
            Expr::If(i) => {
                if let Some(c) = i.cond() {
                    self.walk_expr(c);
                }
                if let Some(t) = i.then_branch() {
                    self.walk_expr(t);
                }
                if let Some(e) = i.else_branch() {
                    self.walk_expr(e);
                }
            }
            Expr::Attrset(a) => {
                // Plain attrset: attrs do not bind inside the set. Only
                // inherit (src) names are recorded (never visible).
                for item in a.items() {
                    match item {
                        AttrItem::Binding(b) => {
                            if let Some(v) = b.value() {
                                self.walk_expr(v);
                            }
                            self.walk_attrpath_interps(b.attrpath());
                        }
                        AttrItem::Inherit(inh) => self.walk_inherit(inh, BindingKind::InheritName, u32::MAX),
                    }
                }
            }
            Expr::RecAttrset(r) => {
                let inner = r.attrset();
                self.push_scope(ScopeKind::Rec, r.range(), None);
                if let Some(set) = inner {
                    // Phase 1: bind every name (mutually visible).
                    for item in set.items() {
                        match item {
                            AttrItem::Binding(b) => {
                                if let Some(name) = first_attr_name(b.attrpath()) {
                                    self.declare(name, BindingKind::RecAttr, r.range().start());
                                }
                            }
                            AttrItem::Inherit(inh) => {
                                for name in inh.names() {
                                    self.declare(name, BindingKind::RecAttr, r.range().start());
                                }
                            }
                        }
                    }
                    // Phase 2: walk values (recursion allowed).
                    for item in set.items() {
                        match item {
                            AttrItem::Binding(b) => {
                                if let Some(v) = b.value() {
                                    self.walk_expr(v);
                                }
                                self.walk_attrpath_interps(b.attrpath());
                            }
                            AttrItem::Inherit(inh) => self.walk_inherit_src(inh),
                        }
                    }
                }
                self.pop_scope();
            }
            Expr::List(l) => {
                for item in l.items() {
                    self.walk_expr(item);
                }
            }
            Expr::Lambda(l) => self.walk_lambda(l),
            Expr::Apply(a) => {
                let mut is_import = false;
                if let Some(f) = a.func() {
                    match f {
                        Expr::Ident(t) if t.text(self.source) == "import" => is_import = true,
                        Expr::Select(sel) => {
                            let base_is_builtins = matches!(
                                sel.base(),
                                Some(Expr::Ident(t)) if t.text(self.source) == "builtins"
                            );
                            let path_is_import = sel
                                .attrpath()
                                .map(|p| {
                                    let r = p.range();
                                    &self.source[r.start() as usize..r.end() as usize] == "import"
                                })
                                .unwrap_or(false);
                            is_import = base_is_builtins && path_is_import;
                        }
                        _ => {}
                    }
                    self.walk_expr(f);
                }
                if let Some(arg) = a.arg() {
                    if is_import {
                        self.import_sites.push(ImportSite {
                            call_range: a.range(),
                            path_range: arg.range(),
                        });
                    }
                    self.walk_expr(arg);
                }
            }
            Expr::Unary(u) => {
                if let Some(o) = u.operand() {
                    self.walk_expr(o);
                }
            }
            Expr::Bin(b) => {
                if let Some(lhs) = b.lhs() {
                    self.walk_expr(lhs);
                }
                if let Some(rhs) = b.rhs() {
                    self.walk_expr(rhs);
                }
            }
            Expr::Select(s) => {
                if let Some(base) = s.base() {
                    self.walk_expr(base);
                }
                // Field names are not references; interpolations inside
                // quoted segments are.
                self.walk_attrpath_interps(s.attrpath());
                if let Some(d) = s.default() {
                    self.walk_expr(d);
                }
            }
            Expr::HasAttr(h) => {
                if let Some(base) = h.base() {
                    self.walk_expr(base);
                }
                // The right side is a field path, not references. Skip
                // (documented limitation: interpolated field names in
                // hasAttr paths are not resolved).
            }
            Expr::String(s) => self.walk_string_parts(s.parts()),
            Expr::IndString(s) => self.walk_string_parts(s.parts()),
            Expr::Paren(p) => {
            Expr::Paren(p) => {
                if let Some(e) = p.expr() {
                    self.walk_expr(e);
                }
            }
            // Atoms carry no references.
            Expr::Int(_)
            | Expr::Float(_)
            | Expr::Path(_)
            | Expr::SearchPath(_)
            | Expr::Uri(_) => {}
        }
    }

    fn walk_let(&mut self, e: strictix_syntax::LetExpr<'a>) {
        self.push_scope(ScopeKind::Let, e.range(), None);
        if let Some(bindings) = e.bindings() {
            for item in bindings.items() {
                match item {
                    AttrItem::Binding(b) => {
                        // Sequential: walk the value first, then declare.
                        let visible_from = b
                            .value()
                            .map_or(b.syntax().range().end(), |v| v.range().end());
                        if let Some(v) = b.value() {
                            self.walk_expr(v);
                        }
                        if let Some(name) = first_attr_name(b.attrpath()) {
                            self.declare(name, BindingKind::LetBinding, visible_from);
                        }
                        self.walk_attrpath_interps(b.attrpath());
                    }
                    AttrItem::Inherit(inh) => {
                        self.walk_inherit(inh, BindingKind::LetBinding, inh.syntax().range().end());
                    }
                }
            }
        }
        if let Some(body) = e.body() {
            self.walk_expr(body);
        }
        self.pop_scope();
    }

    fn walk_lambda(&mut self, l: strictix_syntax::LambdaExpr<'a>) {
        self.push_scope(ScopeKind::Lambda, l.range(), None);
        let body_start = l.body().map_or(l.range().end(), |b| b.range().start());
        match l.param() {
            LambdaParam::Ident(t) => {
                self.declare(t, BindingKind::LambdaParam, t.range().end());
            }
            LambdaParam::Formals(formals, at_name) => {
                for param in formals.params() {
                    // A param is visible in its own default (recursive), so
                    // declare before walking the default.
                    self.declare(param.name, BindingKind::LambdaParam, param.name.range().end());
                    if let Some(default) = param.default {
                        self.walk_expr(default);
                    }
                }
                if let Some(at) = at_name {
                    self.declare(at, BindingKind::AtName, body_start);
                }
            }
        }
        if let Some(body) = l.body() {
            self.walk_expr(body);
        }
        self.pop_scope();
    }

    fn walk_inherit(
        &mut self,
        inh: strictix_syntax::InheritStmt<'a>,
        kind: BindingKind,
        visible_from: u32,
    ) {
        self.walk_inherit_src(inh);
        for name in inh.names() {
            self.declare(name, kind, visible_from);
        }
    }

    fn walk_inherit_src(&mut self, inh: strictix_syntax::InheritStmt<'a>) {
        if let Some(src) = inh.source() {
            self.walk_expr(src);
        }
    }

    fn walk_string_parts(&mut self, parts: impl Iterator<Item = StringPart<'a>>) {
        for part in parts {
            if let StringPart::Interp(interp) = part {
                if let Some(e) = interp.expr() {
                    self.walk_expr(e);
                }
            }
        }
    }

    /// Interpolations inside quoted attrpath segments are real references.
    fn walk_attrpath_interps(&mut self, path: Option<strictix_syntax::Attrpath<'a>>) {
        if let Some(p) = path {
            for element in p.elements() {
                if let AttrName::Str(s) = element {
                    self.walk_string_parts(s.parts());
                }
            }
        }
    }
}

/// The name a binding attrpath binds: its first plain-ident element.
/// Dotted paths bind only the first name; quoted first segments are
/// dynamic and bind nothing statically.
fn first_attr_name<'a>(path: Option<strictix_syntax::Attrpath<'a>>) -> Option<&'a SyntaxToken> {
    let p = path?;
    match p.elements().next()? {
        AttrName::Ident(t) => Some(t),
        AttrName::Str(_) => None,
    }
}

